  var seen = Object.create(null);
  var result = [];
  for (var i = 0; i < arr.length; i++) {
    var obj = arr[i];
    if (obj === null || typeof obj !== 'object') {
      result.push(obj);
      continue;
    }
    var keys = Object.keys(obj).sort();
    var parts = [];
    for (var k = 0; k < keys.length; k++) {
      var key = keys[k];
      parts.push(JSON.stringify(key) + ':' + JSON.stringify(obj[key]));
    }
    var signature = '{' + parts.join(',') + '}';
    if (Object.prototype.hasOwnProperty.call(seen, signature)) {
      continue;
    }
    seen[signature] = true;
    result.push(obj);
  }
  return result;
}",
